#!/usr/bin/env node
/**
 * Compatibility entrypoint for website builds that still call both generators.
 * The schema reference is generated by generate-reference.mjs. There are no
 * narrative guides to publish; remove any previously generated guide subtree.
 * Keep this entrypoint until the consuming website stops calling it directly.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { resolveContentRoot } from './common.mjs';

const websiteRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const contentRoot = resolveContentRoot(process.argv.slice(2), websiteRoot);
fs.rmSync(path.join(contentRoot, 'guides'), { recursive: true, force: true });
console.log('sync-docs: no narrative guides; removed obsolete generated content');
